    BaseClass() {
        setup();
    }
    void setup() {
        System.out.print("Base ");
    }
}
class DerivedClass extends BaseClass {
    int val = 42;
    @Override
    void setup() {
        System.out.print("Derived:" + val + " ");
    }
}
public class Main {
    public static void main(String[] args) {
        new DerivedClass();
    }
}
```

